/* =========================================================
   PassQuest: script.js
   Gamified password-safety learning app for St. Paul University
   Manila SHS students. Plain JavaScript, no framework, no build step.

   HOW DATA IS SAVED
   - Accounts and progress (XP, lessons, checklist, quizzes, badges,
     streak, Habit Mode) are saved in the browser's localStorage
     through sget()/sset() in section 8.
   - Account passwords are stored as salted SHA-256 hashes, never as text.
   - The same events are also written to Supabase (sections 21-22):
     users, consent, user_progress, checklist_responses, user_badges,
     leaderboard, certificates, password_checker_results.

   TABLE OF CONTENTS  (search for the number and a dot, e.g. "14.")
    1. Supabase client
    2. Brand icon
    3. Curriculum: research links + Foundation Track (Levels 1-5)
    4. Curriculum: Advanced Track (Levels 6-10) + XP totals
    5. Habit Mode content
    6. Badges
    7. Small helpers (hashing, date keys, seeded picks)
    8. Local save layer (localStorage)
    9. App state + boot
   10. Progress: XP, streak, Habit Mode refresh, badge checks
   11. Lockie the mascot
   12. Rendering core: router, toasts, effects, celebration popup
   13. Pages: landing, login/register, app shell
   14. Pages: dashboard, learning path, level detail, quiz
   15. Pages: checklist hub, password checker, Habit Mode
   16. Pages: leaderboard, certificates, profile
   17. Password strength engine + Lockie coach
   18. Event wiring
   19. Action handlers
   20. Certificate PNG download
   21. Supabase: data functions
   22. Supabase: page-load hooks
   23. Certificate template images (base64)
   24. Start the app
   ========================================================= */

