/* =========================================================
   7. SMALL HELPERS
   Hashing, date keys and seeded picks for the daily/weekly rotation.
   ========================================================= */
function hashStr(s){ let h=0; for(let i=0;i<s.length;i++){ h = (h<<5)-h + s.charCodeAt(i); h|=0; } return Math.abs(h); }
// Day keys use the student's local date, so daily items reset at local midnight
// (UTC dates made them reset at 8:00 AM in the Philippines).
function localDateKey(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function todayKey(){ return localDateKey(new Date()); }
function monthKey(){ return todayKey().slice(0,7); }
function weekKey(){
  const d = new Date();
  const onejan = new Date(d.getFullYear(),0,1);
  const wk = Math.ceil((((d - onejan)/86400000) + onejan.getDay()+1)/7);
  return d.getFullYear()+'-W'+wk;
}
// Escape text typed by students (names, sections...) before it goes into the page.
function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

// SHA-256 (hex) for PassQuest account passwords, so they are never stored in
// readable form. Plain JavaScript, so it also works when the page is opened as a file.
function sha256(text){
  const ascii = unescape(encodeURIComponent(text));
  const rot = (v,a)=>(v>>>a)|(v<<(32-a));
  const K = [], H = [], words = [];
  let n = 0;
  for(let c=2; n<64; c++){
    let prime = true;
    for(let f=2; f*f<=c; f++) if(c%f===0){ prime=false; break; }
    if(!prime) continue;
    if(n<8) H[n] = (Math.pow(c,1/2)*4294967296)|0;
    K[n++] = (Math.pow(c,1/3)*4294967296)|0;
  }
  let s = ascii + '\x80';
  while(s.length%64 - 56) s += '\x00';
  for(let i=0;i<s.length;i++) words[i>>2] |= s.charCodeAt(i) << ((3-i)%4)*8;
  words.push((ascii.length*8/4294967296)|0, (ascii.length*8)|0);
  let h = H.slice();
  for(let j=0;j<words.length;j+=16){
    const w = words.slice(j, j+16), old = h.slice();
    for(let i=0;i<64;i++){
      if(i>=16){ const a=w[i-15], b=w[i-2]; w[i] = (w[i-16] + (rot(a,7)^rot(a,18)^(a>>>3)) + w[i-7] + (rot(b,17)^rot(b,19)^(b>>>10)))|0; }
      const e=h[4], a=h[0];
      const t1 = h[7] + (rot(e,6)^rot(e,11)^rot(e,25)) + ((e&h[5])^(~e&h[6])) + K[i] + w[i];
      const t2 = (rot(a,2)^rot(a,13)^rot(a,22)) + ((a&h[1])^(a&h[2])^(h[1]&h[2]));
      h = [(t1+t2)|0].concat(h.slice(0,7)); h[4] = (h[4]+t1)|0;
    }
    h = h.map((v,i)=>(v+old[i])|0);
  }
  return h.map(v=>(v>>>0).toString(16).padStart(8,'0')).join('');
}
function newSalt(){
  const a = new Uint8Array(16);
  (window.crypto||window.msCrypto).getRandomValues(a);
  return Array.from(a, b=>b.toString(16).padStart(2,'0')).join('');
}
function hashPassword(pw, salt){ return sha256(salt+':'+pw); }
function checkPassword(user, pw){
  if(user.passwordHash) return hashPassword(pw, user.salt)===user.passwordHash;
  return user.password===pw; // accounts saved before hashing (migrated on load)
}

function seededPick(arr, n, seedStr){
  let seed = hashStr(seedStr);
  const pool = arr.map((v,i)=>({v,i}));
  const out = [];
  for(let k=0;k<n && pool.length;k++){
    seed = (seed*1103515245 + 12345) & 0x7fffffff;
    const idx = seed % pool.length;
    out.push(pool.splice(idx,1)[0].v);
  }
  return out;
}

/* =========================================================
   8. LOCAL SAVE LAYER (localStorage)
   Keys: passquest_users, passquest_session, passquest_progress_<username>
   ========================================================= */
async function sget(key) {
  try {
    const value = localStorage.getItem(key);
    return value ? JSON.parse(value) : null;
  } catch (e) {
    return null;
  }
}

async function sset(key, val) {
  try {
    localStorage.setItem(key, JSON.stringify(val));
  } catch (e) {
    console.error("Storage set failed:", e);
  }
}

/* =========================================================
   9. APP STATE + BOOT
   ========================================================= */
let STATE = {
  view:'landing',
  authMode:'login',
  session:null,       // username
  users:[],           // [{username,name,strand,section,email,password}]
  progress:null,      // current user's progress object
  currentLevel:null,
  levelTab:'lesson',
  quizIndex:0,
  quizPicked:null,
  quizResults:{},     // per-session temp {correct,total}
  quizRetake:false,   // true while retaking a finished quiz for practice
  pendingCertModal:null,
  leaderboardLoading:false,
  leaderboardData:null
};

function freshProgress(){
  return { xp:0, lessonsDone:[], checklistDone:[], quizDone:{}, badges:[], streak:0, lastActiveDate:null, testedStrongPw:false,
    certNotified:false, advCertNotified:false,
    bonusXP:0, missionsCompletedTotal:0, daily:null, weekly:null, monthly:null, leaderboardOptIn:false };
}

async function boot(){
  STATE.users = (await sget('passquest_users')) || [];
  await migratePasswords();
  const session = await sget('passquest_session');
  const sessionUser = session && STATE.users.find(u=>u.username===session);
  if(sessionUser){
    STATE.session = session;
    STATE.progress = (await sget('passquest_progress_'+session)) || freshProgress();
    normalizeProgress();
    await linkSupabaseUser(sessionUser);
    await touchStreak();
    refreshEngagement();
    await saveProgress();
    STATE.view='dashboard';
  }
  render(true);
}

// Older accounts kept their PassQuest password in readable form; replace it with a salted hash.
async function migratePasswords(){
  let changed = false;
  STATE.users.forEach(u=>{
    if(u.password!==undefined && !u.passwordHash){
      u.salt = newSalt(); u.passwordHash = hashPassword(u.password, u.salt); delete u.password; changed = true;
    }
  });
  if(changed) await saveUsers();
}

// Point Supabase saves at the logged-in student (not whoever registered last on this device).
async function linkSupabaseUser(user){
  localStorage.removeItem('passquest_user_id');
  await saveOrGetUser(user.name, user.email, supabaseGradeLevel(user.strand, user.section), user.section);
  // leaderboard rows are only for students who opted in (older versions added everyone)
  if(STATE.progress && !STATE.progress.leaderboardOptIn) removeLeaderboardEntry();
}
// users.grade_level gets the grade from the "Grade & Section" field plus the strand, e.g. "Grade 12 · STEM"
function supabaseGradeLevel(strand, section){
  const m = String(section||'').match(/grade\s*(\d{1,2})/i);
  return m ? 'Grade '+m[1]+' · '+strand : strand;
}

function normalizeProgress(){
  const p = STATE.progress;
  if(p.bonusXP===undefined) p.bonusXP=0;
  if(p.missionsCompletedTotal===undefined) p.missionsCompletedTotal=0;
  if(p.daily===undefined) p.daily=null;
  if(p.weekly===undefined) p.weekly=null;
  if(p.monthly===undefined) p.monthly=null;
  if(p.leaderboardOptIn===undefined) p.leaderboardOptIn=false;
  if(p.certNotified===undefined) p.certNotified = totalXP()>=TOTAL_XP;
  if(p.advCertNotified===undefined) p.advCertNotified = advTotalXP()>=ADV_TOTAL_XP;
}

/* =========================================================
   10. PROGRESS: XP, STREAK, HABIT MODE REFRESH, BADGE CHECKS
   ========================================================= */
/* ---------------- daily/weekly/monthly engagement refresh ---------------- */
function refreshEngagement(){
  const p = STATE.progress;
  const tKey = todayKey();
  if(!p.daily || p.daily.date !== tKey){
    const picks = seededPick(DAILY_MISSION_POOL, 3, tKey+'|'+STATE.session);
    const tipIdx = hashStr(tKey+'|tip') % CYBER_TIPS.length;
    const quizIdx = hashStr(tKey+'|quiz') % ROTATING_QUIZ_POOL.length;
    p.daily = { date:tKey, missions: picks.map(m=>({...m,done:false})), loginClaimed:false, tipIndex:tipIdx, quizIndex:quizIdx, quizAnswered:false, quizCorrect:false };
  }
  if(!p.daily.review){ // three questions from the level quizzes, new every day
    p.daily.review = { picks: seededPick(REVIEW_POOL, 3, tKey+'|review|'+STATE.session).map(r=>[r.levelId, r.qi]), answers:{} };
  }
  const wKey = weekKey();
  if(!p.weekly || p.weekly.key !== wKey){
    const [pick] = seededPick(WEEKLY_CHALLENGE_POOL, 1, wKey);
    p.weekly = { key:wKey, ...pick, done:false };
  }
  const mKey = monthKey();
  if(!p.monthly || p.monthly.key !== mKey){
    p.monthly = { key:mKey, items: MONTHLY_CHECKLIST_POOL.map(i=>({...i,done:false})) };
  }
}
function bonusXP(){ return (STATE.progress && STATE.progress.bonusXP) || 0; }
function grandTotalXP(){ return totalXP() + advTotalXP() + bonusXP(); } // both tracks + Habit Mode bonuses

async function touchStreak(){
  const today = todayKey();
  const p = STATE.progress;
  if(p.lastActiveDate !== today){
    if(p.lastActiveDate){
      const diff = (new Date(today) - new Date(p.lastActiveDate)) / 86400000;
      p.streak = diff === 1 ? p.streak + 1 : 1;
    } else { p.streak = 1; }
    p.lastActiveDate = today;
    await saveProgress();
    checkBadges();
  }
}

async function saveProgress(){
  await sset('passquest_progress_'+STATE.session, STATE.progress);
  if(STATE.progress && STATE.progress.leaderboardOptIn) syncLeaderboardEntry();
}
async function saveUsers(){
  await sset('passquest_users', STATE.users);
}

/* ---------------- xp / badges / level logic ---------------- */
function levelEarnedXP(levelId){
  const p = STATE.progress; if(!p) return 0;
  const lvl = LEVELS.find(l=>l.id===levelId);
  let xp = 0;
  if(p.lessonsDone.includes(levelId)) xp += 20;
  lvl.checklist.forEach(c=>{ if(p.checklistDone.includes(c.id)) xp += c.xp; });
  const qd = p.quizDone[levelId];
  if(qd) xp += qd.xpAwarded;
  return xp;
}
function isLevelComplete(levelId){ return levelEarnedXP(levelId) >= 100; }
function isLevelUnlocked(levelId){ return levelId===1 || isLevelComplete(levelId-1); }
function totalXP(){ return CORE_LEVELS.reduce((s,l)=>s+levelEarnedXP(l.id),0); }
function advTotalXP(){ return ADV_LEVELS.reduce((s,l)=>s+levelEarnedXP(l.id),0); }
function currentLevelNumber(){
  for(const l of LEVELS){ if(!isLevelComplete(l.id)) return l.id; }
  return LEVELS.length;
}

function checkBadges(){
  const p = STATE.progress; const add = id => { if(BADGE_DEFS[id] && !p.badges.includes(id)){ p.badges.push(id); toast(BADGE_DEFS[id].icon, 'Badge earned!', BADGE_DEFS[id].name); saveUserBadge(id); } };
  LEVELS.forEach(l=>{ if(isLevelComplete(l.id)) add('lvl'+l.id); });
  if(ALL_CHECKLIST.every(c=>p.checklistDone.includes(c.id))) add('checklistMaster');
  Object.entries(p.quizDone).forEach(([lid,r])=>{ if(r.correct===r.total) add('quizWhiz'); });
  if(p.streak>=3) add('streak3');
  if(p.streak>=7) add('streak7');
  if(p.streak>=30) add('streak30');
  if(p.testedStrongPw) add('securityAnalyst');
  if(p.weekly && p.weekly.done) add(p.weekly.id);
  if((p.missionsCompletedTotal||0)>=10) add('missionist');
  if((p.missionsCompletedTotal||0)>=30) add('missionMaster');
  if(p.monthly && p.monthly.items.every(i=>i.done)) add('checkupChampion');

  if(totalXP()>=TOTAL_XP && !p.certNotified){ p.certNotified=true; STATE.pendingCertModal='main'; saveProgress(); }
  else if(advTotalXP()>=ADV_TOTAL_XP && !p.advCertNotified){ p.advCertNotified=true; STATE.pendingCertModal='adv'; saveProgress(); }
}

/* =========================================================
   11. LOCKIE THE MASCOT
   mascotSVG(pose, size) builds Lockie as inline SVG.
   Poses: idle, wink, excited, cool, sad, thinking, worried, neutral, radiant.
   Only one Lockie should be visible on screen at a time.
   ========================================================= */
function mascotFace(pose){
  switch(pose){
    case 'wink': return `
      <rect x="61" y="90" width="8" height="12" rx="4" fill="var(--cyan)"/>
      <path d="M89,96 Q97,90 105,96" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M64,110 Q80,120 96,110" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>`;
    case 'excited': return `
      <path d="M56,96 Q65,86 74,96" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M86,96 Q95,86 104,96" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M62,106 Q80,126 98,106 Q80,116 62,106 Z" fill="var(--cyan)"/>`;
    case 'cool': return `
      <rect x="55" y="92" width="50" height="14" rx="6" fill="#0B0E24" stroke="var(--cyan)" stroke-width="2"/>
      <line x1="80" y1="92" x2="80" y2="106" stroke="#0B0E24" stroke-width="3"/>
      <path d="M60,97 Q65,94 70,97" stroke="var(--cyan)" stroke-width="2" fill="none" stroke-linecap="round" opacity=".7"/>
      <path d="M90,97 Q95,94 100,97" stroke="var(--cyan)" stroke-width="2" fill="none" stroke-linecap="round" opacity=".7"/>
      <line x1="68" y1="114" x2="92" y2="114" stroke="var(--cyan)" stroke-width="4" stroke-linecap="round"/>`;
    case 'sad': return `
      <path d="M58,98 Q65,92 72,98" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M88,98 Q95,92 102,98" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M65,118 Q80,106 95,118" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M110,86 Q116,94 110,104" stroke="#67E8F9" stroke-width="4" fill="none" stroke-linecap="round" opacity=".8"/>`;
    case 'thinking': return `
      <rect x="61" y="94" width="8" height="10" rx="4" fill="var(--cyan)"/>
      <rect x="91" y="94" width="8" height="10" rx="4" fill="var(--cyan)"/>
      <path d="M86,86 Q96,80 104,86" stroke="var(--cyan)" stroke-width="3" fill="none" stroke-linecap="round"/>
      <circle cx="80" cy="116" r="4" fill="var(--cyan)"/>`;
    case 'worried': return `
      <path d="M58,92 Q66,98 74,94" stroke="#67E8F9" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M86,94 Q94,98 102,92" stroke="#67E8F9" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M64,98 Q70,92 76,97" stroke="#67E8F9" stroke-width="2.5" fill="none" stroke-linecap="round" opacity=".6"/>
      <path d="M84,97 Q90,92 96,98" stroke="#67E8F9" stroke-width="2.5" fill="none" stroke-linecap="round" opacity=".6"/>
      <path d="M66,116 Q80,108 94,116" stroke="#67E8F9" stroke-width="4" fill="none" stroke-linecap="round"/>
      <path d="M108,84 Q114,92 108,100" stroke="#67E8F9" stroke-width="3.5" fill="none" stroke-linecap="round" opacity=".7"/>`;
    case 'neutral': return `
      <rect x="61" y="96" width="9" height="8" rx="3" fill="var(--cyan)"/>
      <rect x="90" y="96" width="9" height="8" rx="3" fill="var(--cyan)"/>
      <line x1="66" y1="114" x2="94" y2="114" stroke="var(--cyan)" stroke-width="4" stroke-linecap="round"/>`;
    case 'radiant': return `
      <circle cx="65" cy="98" r="7" fill="var(--green)"/>
      <circle cx="95" cy="98" r="7" fill="var(--green)"/>
      <circle cx="65" cy="98" r="11" fill="var(--green)" opacity=".35"/>
      <circle cx="95" cy="98" r="11" fill="var(--green)" opacity=".35"/>
      <path d="M60,110 Q80,128 100,110 Q80,120 60,110 Z" fill="var(--green)"/>`;
    default: return `
      <rect x="61" y="92" width="8" height="12" rx="4" fill="var(--cyan)"/>
      <rect x="91" y="92" width="8" height="12" rx="4" fill="var(--cyan)"/>
      <path d="M64,108 Q80,120 96,108" stroke="var(--cyan)" stroke-width="4" fill="none" stroke-linecap="round"/>`;
  }
}
function mascotShackle(pose){
  if(pose==='worried') return `<path d="M58,60 V44 A22,22 0 0 1 92,26" fill="none" stroke="#C9C4F5" stroke-width="14" stroke-linecap="round"/>`;
  return `<path d="M58,60 V40 A22,22 0 0 1 102,40 V60" fill="none" stroke="#C9C4F5" stroke-width="14" stroke-linecap="round"/>`;
}
function mascotArms(pose){
  if(pose==='excited') return `
    <rect x="20" y="60" width="12" height="34" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(-95 26 94)"/>
    <rect x="128" y="60" width="12" height="34" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(95 134 94)"/>`;
  if(pose==='sad') return `
    <rect x="24" y="96" width="12" height="30" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(18 30 96)"/>
    <rect x="124" y="96" width="12" height="30" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(-18 130 96)"/>`;
  if(pose==='wink') return `
    <rect x="20" y="88" width="12" height="32" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(-30 26 90)"/>
    <rect x="128" y="94" width="12" height="30" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(8 134 96)"/>`;
  if(pose==='worried') return `
    <rect x="26" y="100" width="12" height="28" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(22 32 102)"/>
    <rect x="122" y="100" width="12" height="28" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(-22 128 102)"/>`;
  if(pose==='radiant') return `
    <rect x="20" y="72" width="12" height="34" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(-55 26 96)"/>
    <rect x="128" y="72" width="12" height="34" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(55 134 96)"/>`;
  return `
    <rect x="22" y="94" width="12" height="30" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(10 28 96)"/>
    <rect x="126" y="94" width="12" height="30" rx="6" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2" transform="rotate(-10 132 96)"/>`;
}
function mascotExtras(pose){
  if(pose==='excited') return `
    <g class="mascot-sparkle">
      <path d="M18,40 l3,8 l8,3 l-8,3 l-3,8 l-3,-8 l-8,-3 l8,-3 Z" fill="var(--amber)"/>
      <path d="M140,30 l2,6 l6,2 l-6,2 l-2,6 l-2,-6 l-6,-2 l6,-2 Z" fill="var(--cyan)"/>
    </g>`;
  if(pose==='thinking') return `<text x="118" y="55" font-family="var(--font-display)" font-size="26" font-weight="700" fill="var(--amber)">?</text>`;
  if(pose==='radiant') return `
    <g class="mascot-sparkle">
      <path d="M22,44 l3,7 l7,3 l-7,3 l-3,7 l-3,-7 l-7,-3 l7,-3 Z" fill="var(--green)"/>
      <path d="M138,50 l2,6 l6,2 l-6,2 l-2,6 l-2,-6 l-6,-2 l6,-2 Z" fill="var(--green)"/>
    </g>`;
  return '';
}
function mascotSVG(pose='idle', size=140){
  const glow = pose==='radiant' ? ' mascot-glow' : (pose==='worried' ? ' mascot-dim' : '');
  return `<svg class="mascot${glow}" data-pose="${pose}" width="${size}" height="${size*1.15|0}" viewBox="0 0 160 184" xmlns="http://www.w3.org/2000/svg">
    <ellipse cx="80" cy="174" rx="34" ry="6" fill="#000" opacity=".18"/>
    <g class="mascot-legs">
      <rect x="60" y="140" width="14" height="28" rx="7" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2"/>
      <rect x="86" y="140" width="14" height="28" rx="7" fill="#DAD6FF" stroke="var(--purple-dim)" stroke-width="2"/>
      <ellipse cx="67" cy="169" rx="11" ry="6" fill="#EDEBFF" stroke="var(--purple-dim)" stroke-width="2"/>
      <ellipse cx="93" cy="169" rx="11" ry="6" fill="#EDEBFF" stroke="var(--purple-dim)" stroke-width="2"/>
    </g>
    ${mascotShackle(pose)}
    ${mascotArms(pose)}
    <rect x="28" y="56" width="104" height="92" rx="34" fill="#F1EFFF" stroke="var(--purple-dim)" stroke-width="3"/>
    <rect x="49" y="80" width="62" height="46" rx="16" fill="#12153a" stroke="#20234c" stroke-width="2"/>
    ${mascotFace(pose)}
    <circle cx="80" cy="134" r="7" fill="var(--cyan)" opacity=".9"/>
    <rect x="76.5" y="138" width="7" height="9" rx="2" fill="var(--cyan)" opacity=".9"/>
    ${mascotExtras(pose)}
  </svg>`;
}

/* =========================================================
   12. RENDERING CORE
   Router, toasts, scroll effects, track-completion popup.
   ========================================================= */
/* ---------------- render router ---------------- */
function render(scrollTop){
  const app = document.getElementById('app');
  if(STATE.view==='landing') app.innerHTML = `<div class="page-anim">${viewLanding()}</div>`;
  else if(STATE.view==='login') app.innerHTML = viewAuth('login');
  else if(STATE.view==='register') app.innerHTML = viewAuth('register');
  else app.innerHTML = viewAppShell();
  bindEvents();
  if(scrollTop) window.scrollTo({top:0});
  initFX();
  fitCertText();
  if(STATE.pendingCertModal){
    const kind = STATE.pendingCertModal;
    STATE.pendingCertModal = null;
    showCertCelebration(kind);
  }
}

// On-screen certificate: shrink the date/grade/name text until it fits its
// placeholder, like the downloaded PNG does (they were cut off with "...").
function fitCertText(){
  document.querySelectorAll('.cert-photo .cf-name, .cert-photo .cf-date, .cert-photo .cf-grade').forEach(el=>{
    el.style.fontSize = '';
    let size = parseFloat(getComputedStyle(el).fontSize);
    const min = el.classList.contains('cf-name') ? 10 : 4;
    while(el.scrollWidth > el.clientWidth + 0.5 && size > min){ size -= 0.5; el.style.fontSize = size+'px'; }
  });
}
let certFitTimer;
window.addEventListener('resize', ()=>{ clearTimeout(certFitTimer); certFitTimer = setTimeout(fitCertText, 150); });

/* ---------------- toast ---------------- */
function toast(icon,title,msg){
  const host = document.getElementById('toastHost');
  const el = document.createElement('div');
  el.className='toast';
  el.innerHTML = `<div class="t-ico">${icon}</div><div><b>${title}</b><span>${msg}</span></div>`;
  host.appendChild(el);
  setTimeout(()=>{ el.style.opacity='0'; el.style.transform='translateX(30px)'; el.style.transition='all .3s'; setTimeout(()=>el.remove(),300); }, 3400);
}

/* ---------------- visual fx: scroll reveal + count-up ---------------- */
function initFX(){
  const reveals = document.querySelectorAll('.reveal:not(.fx-bound)');
  if('IntersectionObserver' in window){
    const io = new IntersectionObserver((entries)=>{
      entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('in-view'); io.unobserve(en.target); } });
    }, {threshold:.15});
    reveals.forEach(el=>{ el.classList.add('fx-bound'); io.observe(el); });
  } else {
    reveals.forEach(el=>{ el.classList.add('fx-bound','in-view'); });
  }

  document.querySelectorAll('[data-count]:not(.fx-bound)').forEach(el=>{
    el.classList.add('fx-bound');
    const target = parseInt(el.getAttribute('data-count'),10) || 0;
    const dur = 900; const start = performance.now();
    function tick(now){
      const p = Math.min(1, (now-start)/dur);
      const eased = 1 - Math.pow(1-p, 3);
      el.textContent = Math.round(eased*target);
      if(p<1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  });
}

/* ---------------- track-completion celebration popup ---------------- */
function showCertCelebration(kind){
  const isAdv = kind==='adv';
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay cert-celebrate-overlay';
  overlay.innerHTML = `
    <div class="modal-box cert-celebrate-box pop">
      <div class="cert-celebrate-mascot mascot-pop">${mascotSVG('radiant',120)}</div>
      <div class="cert-celebrate-confetti">🎉 ✨ 🎊</div>
      <h2 style="margin:4px 0 8px">${isAdv? 'Advanced Track complete!' : 'Foundation Track complete!'}</h2>
      <p style="color:var(--text-dim);margin-bottom:8px">You finished ${isAdv? 'all 5 Advanced Track levels' : 'all 5 core levels'} and unlocked a certificate.</p>
      <p style="font-family:var(--font-display);font-weight:800;font-size:21px;color:var(--amber);margin-bottom:24px">${isAdv? '🎖️ Cyber Sentinel' : '🏆 Password Safety Champion'}</p>
      <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-primary" id="celebViewCertBtn">View my certificate →</button>
        <button class="btn btn-ghost" id="celebCloseBtn">Keep exploring</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  document.body.classList.add('celebrating'); // hides the page's own Lockie (one Lockie on screen at a time)
  const close = ()=>{ overlay.remove(); document.body.classList.remove('celebrating'); };
  overlay.querySelector('#celebCloseBtn').addEventListener('click', close);
  overlay.querySelector('#celebViewCertBtn').addEventListener('click', ()=>{
    close(); STATE.view='certificate'; render(true);
  });
  overlay.addEventListener('click',(e)=>{ if(e.target===overlay) close(); });
}

