/* =========================================================
   17. PASSWORD STRENGTH ENGINE + LOCKIE COACH
   analyzePassword() scores a password; coachAdvice() picks Lockie's pose
   and speech bubble (priority order: common word, pattern, repeats,
   length, number, symbol, case, then strength band);
   updatePwChecker() paints the checker page as the user types.
   ========================================================= */
const COMMON_PW = ["password","123456","12345678","qwerty","111111","abc123","iloveyou","admin","letmein","welcome","password123","monkey","dragon","football","123123","000000","987654321","qwertyuiop"];

function analyzePassword(pw){
  const checks = { len: pw.length>=12, upper:/[A-Z]/.test(pw), lower:/[a-z]/.test(pw), num:/[0-9]/.test(pw), sym:/[^A-Za-z0-9]/.test(pw) };
  const lower = pw.toLowerCase();
  const isCommon = COMMON_PW.includes(lower);
  const isSequential = /0123|1234|2345|3456|4567|5678|6789|abcd|bcde|cdef|qwer|asdf/.test(lower);
  const isRepeated = /(.)\1{2,}/.test(pw);
  const personalOk = !isCommon && !isSequential && !isRepeated;
  checks.personal = personalOk && pw.length>0;

  let score = 0;
  if(pw.length>0){
    score += Math.min(40, pw.length*3);
    if(checks.upper) score+=12;
    if(checks.lower) score+=12;
    if(checks.num) score+=12;
    if(checks.sym) score+=14;
    if(!personalOk) score = Math.min(score,25);
  }
  score = Math.max(0, Math.min(100, Math.round(score)));

  let label='Very Weak', color='var(--red)';
  if(pw.length===0){ label=''; }
  else if(score<30){ label='Very Weak'; color='var(--red)'; }
  else if(score<50){ label='Weak'; color='#FB923C'; }
  else if(score<70){ label='Fair'; color='var(--amber)'; }
  else if(score<88){ label='Strong'; color='var(--green)'; }
  else { label='Very Strong'; color='var(--green)'; }

  const tips=[];
  if(pw.length>0){
    if(!checks.len) tips.push('Use at least 12 characters — longer passwords are exponentially harder to crack.');
    if(!checks.upper) tips.push('Add at least one uppercase letter.');
    if(!checks.lower) tips.push('Add at least one lowercase letter.');
    if(!checks.num) tips.push('Include at least one number.');
    if(!checks.sym) tips.push('Include a symbol like ! @ # or %.');
    if(isCommon) tips.push('This is a commonly leaked password — never use it.');
    if(isSequential) tips.push('Avoid sequential patterns like "1234" or "qwer".');
    if(isRepeated) tips.push('Avoid repeating the same character multiple times in a row.');
    if(tips.length===0) tips.push('Great job! This password meets all core strength criteria.');
  }
  return {score,label,color,checks,tips,isCommon,isSequential,isRepeated};
}

/* ---- Lockie the coach: reactive expression + speech-bubble tip ---- */
function coachAdvice(r, val){
  if(!val.length) return {pose:'neutral', msg:"Type a password and I'll help you make it stronger!"};
  let pose = 'worried';
  if(r.score>=70) pose='radiant';
  else if(r.score>=50) pose='neutral';

  let msg;
  if(r.isCommon) msg = "That's a common word, that one's too easy to guess!";
  else if(r.isSequential) msg = "That's a predictable pattern, mix up the order so I'm harder to crack!";
  else if(r.isRepeated) msg = "Too many repeated characters in a row, vary them up so I'm tougher to guess!";
  else if(!r.checks.len) msg = "The password's too short, add a little more length so I can lock up tight!";
  else if(!r.checks.num) msg = "No numbers yet, add a number so I'll feel safer!";
  else if(!r.checks.sym) msg = "Try adding a symbol like ! @ or #, it makes me much tougher to pick.";
  else if(!r.checks.upper) msg = "Add an uppercase letter, every bit of variety helps!";
  else if(!r.checks.lower) msg = "Add a lowercase letter too, for good mixing.";
  else if(r.score<70) msg = "Getting there! A little more length or variety and I'll be rock solid.";
  else if(r.score<88) msg = "Nice and strong! One more tweak and I'll be glowing at full power.";
  else msg = "Perfect! I'm locked up tight and glowing. Excellent password!";
  return {pose,msg};
}

function genPassword(){
  const upper='ABCDEFGHJKLMNPQRSTUVWXYZ', lower='abcdefghijkmnpqrstuvwxyz', nums='23456789', syms='!@#$%^&*-_+=?';
  const all = upper+lower+nums+syms;
  let pw = [upper,lower,nums,syms].map(set=>set[Math.floor(Math.random()*set.length)]).join('');
  for(let i=0;i<10;i++) pw += all[Math.floor(Math.random()*all.length)];
  return pw.split('').sort(()=>Math.random()-0.5).join('');
}

function updatePwChecker(val){
  const r = analyzePassword(val);
  const bar = document.getElementById('pwBar');
  const label = document.getElementById('pwLabel');
  const scoreTxt = document.getElementById('pwScoreTxt');
  bar.style.width = r.score+'%';
  bar.style.background = val.length? r.color : 'var(--elev-2)';
  label.textContent = val.length? r.label : 'Enter a password above';
  label.style.color = val.length? r.color : 'var(--text-dim)';
  scoreTxt.textContent = val.length? r.score+' / 100' : '';

  Object.entries(r.checks).forEach(([k,v])=>{
    const row = document.getElementById('req_'+k);
    if(!row) return;
    row.classList.toggle('pass', v && val.length>0);
    row.querySelector('.ico').textContent = (v && val.length>0) ? '✓' : '○';
  });

  const tipsBox = document.getElementById('pwTips');
  const tipsList = document.getElementById('pwTipsList');
  if(val.length===0){ tipsBox.style.display='none'; }
  else{
    tipsBox.style.display='block';
    tipsList.innerHTML = r.tips.map(t=>`<li>${t}</li>`).join('');
  }

  if(r.score>=88 && STATE.progress && !STATE.progress.testedStrongPw){
    STATE.progress.testedStrongPw = true;
    saveProgress().then(checkBadges);
  }

  const coach = coachAdvice(r, val);
  const mascotWrap = document.getElementById('lockieMascotWrap');
  const bubble = document.getElementById('lockieBubble');
  if(mascotWrap && mascotWrap.dataset.pose !== coach.pose){
    mascotWrap.innerHTML = mascotSVG(coach.pose, 84);
    mascotWrap.dataset.pose = coach.pose;
  }
  if(bubble && bubble.dataset.msg !== coach.msg){
    bubble.innerHTML = `<span class="bubble-text-pop">${coach.msg}</span>`;
    bubble.dataset.msg = coach.msg;
  }

  queueCheckerSave(r, val);
}

/* =========================================================
   18. EVENT WIRING
   Called after every render() to attach click/submit handlers.
   ========================================================= */
function bindEvents(){
  document.querySelectorAll('[data-go]').forEach(el=>{
    el.addEventListener('click',async (e)=>{
      e.preventDefault();
      const target = el.getAttribute('data-go');
      if(target==='landing'){ STATE.view='landing'; render(true); return; }
      if(target==='login'||target==='register'){ STATE.view=target; render(true); return; }
      if(target==='level-detail'){
        STATE.currentLevel = parseInt(el.getAttribute('data-level')||STATE.currentLevel||1);
        STATE.levelTab='lesson'; STATE.quizIndex=0; STATE.quizPicked=null; STATE.quizRetake=false;
        STATE.view='level-detail'; render(true); return;
      }
      if(target==='leaderboard'){
        STATE.view='leaderboard';
        if(STATE.progress && STATE.progress.leaderboardOptIn){ loadLeaderboard(); } else { render(true); }
        return;
      }
      STATE.view = target; render(true);
    });
  });

  document.querySelectorAll('[data-scroll]').forEach(el=>{
    el.addEventListener('click',(e)=>{ e.preventDefault(); document.getElementById(el.getAttribute('data-scroll'))?.scrollIntoView({behavior:'smooth'}); });
  });

  document.querySelectorAll('.pw-eye').forEach(el=>{
    el.addEventListener('click',()=>{
      const input = document.getElementById(el.getAttribute('data-eyefor'));
      if(input) input.type = input.type==='password'?'text':'password';
    });
  });

  const loginForm = document.getElementById('loginForm');
  if(loginForm) loginForm.addEventListener('submit', handleLogin);
  const regForm = document.getElementById('regForm');
  if(regForm) regForm.addEventListener('submit', handleRegister);

  const termsModal = document.getElementById('termsModal');
  document.querySelectorAll('[data-open-terms]').forEach(el=>{
    el.addEventListener('click',(e)=>{
      e.preventDefault();
      termsModal?.classList.remove('hidden');
      const box = termsModal?.querySelector('.modal-box');
      if(box){ box.classList.remove('pop'); void box.offsetWidth; box.classList.add('pop'); }
    });
  });
  const closeTermsBtn = document.getElementById('closeTermsBtn');
  const closeTermsX = document.getElementById('closeTermsX');
  const agreeTermsBtn = document.getElementById('agreeTermsBtn');
  if(closeTermsBtn) closeTermsBtn.addEventListener('click', ()=> termsModal?.classList.add('hidden'));
  if(closeTermsX) closeTermsX.addEventListener('click', ()=> termsModal?.classList.add('hidden'));
  if(agreeTermsBtn) agreeTermsBtn.addEventListener('click', ()=>{
    const cb = document.getElementById('r_terms'); if(cb) cb.checked = true;
    termsModal?.classList.add('hidden');
  });
  if(termsModal) termsModal.addEventListener('click',(e)=>{ if(e.target===termsModal) termsModal.classList.add('hidden'); });

  const badgeModal = document.getElementById('badgeModal');
  document.querySelectorAll('[data-badge]').forEach(el=>{
    el.addEventListener('click', ()=>{
      const b = BADGE_DEFS[el.getAttribute('data-badge')];
      if(!b || !badgeModal) return;
      const hexEl = document.getElementById('badgeModalHex');
      hexEl.className = 'hex '+b.cls;
      hexEl.textContent = b.icon;
      document.getElementById('badgeModalName').textContent = b.name;
      document.getElementById('badgeModalDesc').textContent = b.desc || '';
      badgeModal.classList.remove('hidden');
      const box = document.getElementById('badgeModalBox');
      if(box){ box.classList.remove('pop'); void box.offsetWidth; box.classList.add('pop'); }
    });
  });
  const closeBadgeModal = document.getElementById('closeBadgeModal');
  if(closeBadgeModal) closeBadgeModal.addEventListener('click', ()=> badgeModal?.classList.add('hidden'));
  if(badgeModal) badgeModal.addEventListener('click',(e)=>{ if(e.target===badgeModal) badgeModal.classList.add('hidden'); });

  const logoutBtn = document.getElementById('logoutBtn');
  if(logoutBtn) logoutBtn.addEventListener('click', handleLogout);

  document.querySelectorAll('[data-dtab]').forEach(el=>{
    el.addEventListener('click',()=>{ STATE.levelTab = el.getAttribute('data-dtab'); STATE.quizIndex=0; STATE.quizPicked=null; render(!el.classList.contains('dtab')); });
  });

  const markLessonBtn = document.getElementById('markLessonBtn');
  if(markLessonBtn) markLessonBtn.addEventListener('click', handleMarkLesson);

  document.querySelectorAll('[data-check]').forEach(el=>{
    el.addEventListener('click', ()=>handleCheckTask(el.getAttribute('data-check'), parseInt(el.getAttribute('data-xp'))));
  });

  document.querySelectorAll('[data-qopt]').forEach(el=>{
    el.addEventListener('click', ()=>handleQuizPick(parseInt(el.getAttribute('data-qopt'))));
  });
  const nextQBtn = document.getElementById('nextQBtn');
  if(nextQBtn) nextQBtn.addEventListener('click', handleNextQuestion);
  const retakeBtn = document.getElementById('retakeQuizBtn');
  if(retakeBtn) retakeBtn.addEventListener('click', ()=>{ STATE.quizRetake=true; STATE.quizIndex=0; STATE.quizPicked=null; render(); });

  const pwInput = document.getElementById('pwInput');
  if(pwInput) pwInput.addEventListener('input', ()=>updatePwChecker(pwInput.value));
  const pwEyeBtn = document.getElementById('pwEyeBtn');
  if(pwEyeBtn) pwEyeBtn.addEventListener('click', ()=>{ pwInput.type = pwInput.type==='password'?'text':'password'; });
  const genPwBtn = document.getElementById('genPwBtn');
  if(genPwBtn) genPwBtn.addEventListener('click', ()=>{ document.getElementById('genPwDisplay').textContent = genPassword(); });

  const downloadCertBtn = document.getElementById('downloadCertBtn');
  if(downloadCertBtn) downloadCertBtn.addEventListener('click', downloadCertificate);
  const downloadAdvCertBtn = document.getElementById('downloadAdvCertBtn');
  if(downloadAdvCertBtn) downloadAdvCertBtn.addEventListener('click', downloadAdvCertificate);

  document.querySelectorAll('[data-mission]').forEach(el=>{
    el.addEventListener('click', ()=>handleClaimMission(el.getAttribute('data-mission'), parseInt(el.getAttribute('data-xp'))));
  });
  const claimLoginBtn = document.getElementById('claimLoginBtn');
  if(claimLoginBtn) claimLoginBtn.addEventListener('click', handleClaimLogin);
  const claimWeeklyBtn = document.getElementById('claimWeeklyBtn');
  if(claimWeeklyBtn) claimWeeklyBtn.addEventListener('click', handleClaimWeekly);
  document.querySelectorAll('[data-rqopt]').forEach(el=>{
    el.addEventListener('click', ()=>handleRotatingQuizPick(parseInt(el.getAttribute('data-rqopt'))));
  });
  document.querySelectorAll('[data-monthly]').forEach(el=>{
    el.addEventListener('click', ()=>handleMonthlyCheck(el.getAttribute('data-monthly')));
  });
  document.querySelectorAll('[data-act]').forEach(el=>{
    el.addEventListener('click', ()=>handlePracticePick('act', +el.getAttribute('data-act'), +el.getAttribute('data-actopt')));
  });
  document.querySelectorAll('[data-scn]').forEach(el=>{
    el.addEventListener('click', ()=>handlePracticePick('scn', +el.getAttribute('data-scn'), +el.getAttribute('data-scnopt')));
  });
  document.querySelectorAll('[data-review]').forEach(el=>{
    el.addEventListener('click', ()=>handleReviewPick(+el.getAttribute('data-review'), +el.getAttribute('data-ropt')));
  });
  const joinLbBtn = document.getElementById('joinLeaderboardBtn');
  if(joinLbBtn) joinLbBtn.addEventListener('click', handleJoinLeaderboard);
  const leaveLbBtn = document.getElementById('leaveLeaderboardBtn');
  if(leaveLbBtn) leaveLbBtn.addEventListener('click', handleLeaveLeaderboard);
}

/* =========================================================
   19. ACTION HANDLERS
   Login, register, lessons, checklist, quiz, Habit Mode, leaderboard.
   ========================================================= */
function showFormMsg(text, ok){
  const el = document.getElementById('formMsg');
  if(!el) return;
  el.textContent = text; el.className = 'form-msg show ' + (ok?'ok':'err');
}

async function handleLogin(e){
  e.preventDefault();
  const username = document.getElementById('li_username').value.trim();
  const password = document.getElementById('li_password').value;
  const user = STATE.users.find(u=>u.username===username && checkPassword(u, password));
  if(!user){ showFormMsg('Incorrect username or password. Please try again.', false); return; }
  STATE.session = username;
  await sset('passquest_session', username);
  STATE.progress = (await sget('passquest_progress_'+username)) || freshProgress();
  normalizeProgress();
  await linkSupabaseUser(user);
  await touchStreak();
  refreshEngagement();
  await saveProgress();
  STATE.view='dashboard';
  render(true);
  toast('👋','Welcome back!', esc(user.name.split(' ')[0])+', continue your quest.');
}

async function handleRegister(e){
  e.preventDefault();
  const name = document.getElementById('r_name').value.trim();
  const strand = document.getElementById('r_strand').value;
  const section = document.getElementById('r_section').value.trim();
  const email = document.getElementById('r_email').value.trim();
  const username = document.getElementById('r_username').value.trim();
  const password = document.getElementById('r_password').value;

  if(username.length<3){ showFormMsg('Username must be at least 3 characters.', false); return; }
  if(password.length<6){ showFormMsg('Password must be at least 6 characters.', false); return; }
  if(STATE.users.find(u=>u.username===username)){ showFormMsg('That username is already taken.', false); return; }
  if(!document.getElementById('r_terms').checked){ showFormMsg('Please agree to the Terms and Conditions to create an account.', false); return; }

  const salt = newSalt();
  const newUser = {name,strand,section,email,username,salt,passwordHash:hashPassword(password, salt)};
  STATE.users.push(newUser);
  await saveUsers();
  localStorage.removeItem('passquest_user_id');
  await saveOrGetUser(name, email, supabaseGradeLevel(strand, section), section);
  await saveConsent(true);
  STATE.session = username;
  await sset('passquest_session', username);
  STATE.progress = freshProgress();
  await touchStreak();
  refreshEngagement();
  await saveProgress();
  STATE.view='dashboard';
  render(true);
  toast('🎉','Account created!', 'Welcome to PassQuest, '+esc(name.split(' ')[0])+'!');
}

async function handleLogout(){
  await sset('passquest_session', null);
  localStorage.removeItem('passquest_user_id');
  STATE.session=null; STATE.progress=null; STATE.view='landing';
  render(true);
}

async function handleMarkLesson(){
  const lvl = LEVELS.find(l=>l.id===STATE.currentLevel);
  if(STATE.progress.lessonsDone.includes(lvl.id) || !practiceStatus(lvl).complete) return;
  STATE.progress.lessonsDone.push(lvl.id);
  await saveProgress();
  await saveUserProgress(lvl.id, true, 20);
  checkBadges();
  toast('📖','Lesson complete!', '+20 XP earned');
  render();
}

async function handleCheckTask(taskId, xp){
  const p = STATE.progress;
  if(p.checklistDone.includes(taskId)) return;
  p.checklistDone.push(taskId);
  await saveProgress();
  await saveUserProgress(taskId, true, xp);
  await saveChecklistResponse(taskId, true);
  checkBadges();
  toast('✅','Task completed!', '+'+xp+' XP earned');
  render();
}
async function handleClaimMission(id, xp){
  const p = STATE.progress;
  const mi = p.daily.missions.find(m=>m.id===id);
  if(!mi || mi.done) return;
  mi.done = true;
  p.bonusXP = (p.bonusXP||0) + xp;
  p.missionsCompletedTotal = (p.missionsCompletedTotal||0) + 1;
  await saveProgress();
  checkBadges();
  await syncLeaderboardEntry();
  toast('📆','Mission complete!', '+'+xp+' XP earned');
  render();
}
async function handleClaimLogin(){
  const p = STATE.progress;
  if(p.daily.loginClaimed) return;
  const bonus = Math.min(20, 5 + p.streak);
  p.daily.loginClaimed = true;
  p.bonusXP = (p.bonusXP||0) + bonus;
  await saveProgress();
  await syncLeaderboardEntry();
  toast('🔥','Login reward claimed!', '+'+bonus+' XP earned');
  render();
}
async function handleClaimWeekly(){
  const p = STATE.progress;
  if(p.weekly.done) return;
  p.weekly.done = true;
  p.bonusXP = (p.bonusXP||0) + p.weekly.xp;
  await saveProgress();
  checkBadges();
  await syncLeaderboardEntry();
  toast('🏁','Weekly challenge complete!', '+'+p.weekly.xp+' XP and a new badge');
  render();
}
async function handleMonthlyCheck(id){
  const p = STATE.progress;
  const item = p.monthly.items.find(i=>i.id===id);
  if(!item || item.done) return;
  item.done = true;
  p.bonusXP = (p.bonusXP||0) + 8;
  await saveProgress();
  checkBadges();
  await syncLeaderboardEntry();
  toast('🗓️','Checked off!', '+8 XP earned');
  render();
}
async function handleRotatingQuizPick(i){
  const p = STATE.progress;
  if(p.daily.quizAnswered) return;
  const rq = ROTATING_QUIZ_POOL[p.daily.quizIndex];
  const correct = i===rq.answer;
  p.daily.quizAnswered = true;
  p.daily.quizCorrect = correct;
  if(correct){ p.bonusXP = (p.bonusXP||0) + 9; }
  await saveProgress();
  await syncLeaderboardEntry();
  toast(correct?'🧠':'🤔', correct?'Correct!':'Not quite', correct?'+9 XP earned':'Check tomorrow for a new question');
  render();
}
async function handleJoinLeaderboard(){
  STATE.progress.leaderboardOptIn = true;
  await saveProgress();
  await syncLeaderboardEntry();
  toast('📊','You joined the leaderboard!', 'Your total XP is now visible to other students.');
  loadLeaderboard();
}
async function handleLeaveLeaderboard(){
  STATE.progress.leaderboardOptIn = false;
  await saveProgress();
  await removeLeaderboardEntry();
  toast('👋','Left the leaderboard', 'Your XP is now private again.');
  render();
}

// Practice answers live for this visit only; finishing them unlocks "Complete lesson".
function handlePracticePick(kind, i, j){
  const lvl = LEVELS.find(l=>l.id===STATE.currentLevel);
  const st = practiceState(lvl);
  if(kind==='act'){
    if(st.act[i]!==undefined) return;
    st.act[i] = j;
  } else {
    const tried = st.scn[i] = st.scn[i] || [];
    if(tried.includes(j) || tried.some(k=>lvl.practice.scenarios[i].opts[k].ok)) return;
    tried.push(j);
  }
  render();
}
async function handleReviewPick(k, j){
  const p = STATE.progress, rv = p.daily.review;
  if(rv.answers[k]!==undefined) return;
  const [lid, qi] = rv.picks[k];
  const correct = LEVELS.find(l=>l.id===lid).quiz[qi].answer===j;
  rv.answers[k] = j;
  if(correct) p.bonusXP = (p.bonusXP||0) + 5;
  await saveProgress();
  toast(correct?'🔁':'🤔', correct?'Correct!':'Not quite', correct?'+5 XP earned':'Read the explanation, then try the next one');
  render();
}

function handleQuizPick(i){
  if(STATE.quizPicked!==null) return;
  STATE.quizPicked = i;
  render();
}

async function handleNextQuestion(){
  const lvl = LEVELS.find(l=>l.id===STATE.currentLevel);
  const q = lvl.quiz[STATE.quizIndex];
  if(!STATE.quizResults[lvl.id]) STATE.quizResults[lvl.id] = {correct:0,total:0,xp:0};
  const r = STATE.quizResults[lvl.id];
  r.total++;
  if(STATE.quizPicked===q.answer){ r.correct++; r.xp += q.xp; }

  if(STATE.quizIndex < lvl.quiz.length-1){
    STATE.quizIndex++; STATE.quizPicked=null; render(); return;
  }
  // finished this attempt — always keep the BEST score, so retakes can raise your XP
  const prev = STATE.progress.quizDone[lvl.id];
  if(!prev){
    STATE.progress.quizDone[lvl.id] = {correct:r.correct,total:r.total,xpAwarded:r.xp};
    await saveProgress();
    checkBadges();
    toast('🎯','Quiz complete!', `${r.correct}/${r.total} correct — +${r.xp} XP`);
  } else if(r.correct > prev.correct){
    const gained = Math.max(0, r.xp - prev.xpAwarded);
    STATE.progress.quizDone[lvl.id] = {correct:r.correct,total:r.total,xpAwarded:r.xp};
    await saveProgress();
    checkBadges();
    toast('🎯','New best score!', `${r.correct}/${r.total} correct — +${gained} XP`);
  } else {
    toast('🎯','Practice complete!', `${r.correct}/${r.total} correct this round`);
  }
  STATE.quizResults[lvl.id] = {correct:0,total:0,xp:0};
  STATE.quizRetake=false;
  render();
}

/* =========================================================
   20. CERTIFICATE PNG DOWNLOAD
   Draws the template image on a canvas, masks the NAME / DATE / GRADE
   placeholders with the template navy (#0C024C), then writes the
   student's details. Coordinates are for a 1400x989 working size.
   ========================================================= */
function downloadCertificate(){
  drawCertificatePNG(CERT_TEMPLATE_URI, 'PassQuest_Certificate_', 'Congratulations, Password Safety Champion!');
}
function downloadAdvCertificate(){
  drawCertificatePNG(CERT_ADV_TEMPLATE_URI, 'PassQuest_Advanced_Certificate_', 'Congratulations, Cyber Sentinel!');
}

function drawCertificatePNG(templateURI, filePrefix, toastMsg){
  const user = STATE.users.find(u=>u.username===STATE.session);
  const img = new Image();
  img.onload = function(){
    const canvas = document.createElement('canvas');
    canvas.width = img.naturalWidth; canvas.height = img.naturalHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    const sx = canvas.width/1400, sy = canvas.height/989;
    ctx.fillStyle = '#0C024C';
    function maskRect(cx,cy,w,h){ ctx.fillRect((cx-w/2)*sx, (cy-h/2)*sy, w*sx, h*sy); }
    maskRect(701.75,441,374.9,91.6);
    maskRect(358.75,842.1,244.9,39.6);
    maskRect(1080.8,842.1,163,39.6);

    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillStyle='#ffffff';

    let nameSize = 46*sx;
    ctx.font = `800 ${nameSize}px 'Space Grotesk', Georgia, sans-serif`;
    while(ctx.measureText(user.name).width > 355*sx && nameSize>14){
      nameSize -= 2;
      ctx.font = `800 ${nameSize}px 'Space Grotesk', Georgia, sans-serif`;
    }
    ctx.fillText(user.name, 701.75*sx, 441*sy);

    const today = new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
    let dateSize = 15*sx;
    ctx.font = `700 ${dateSize}px 'JetBrains Mono', monospace`;
    while(ctx.measureText(today).width > 232*sx && dateSize>8){
      dateSize -= 1;
      ctx.font = `700 ${dateSize}px 'JetBrains Mono', monospace`;
    }
    ctx.fillText(today, 358.75*sx, 842.1*sy);

    let gradeSize = 15*sx;
    ctx.font = `700 ${gradeSize}px 'JetBrains Mono', monospace`;
    while(ctx.measureText(user.section).width > 155*sx && gradeSize>8){
      gradeSize -= 1;
      ctx.font = `700 ${gradeSize}px 'JetBrains Mono', monospace`;
    }
    ctx.fillText(user.section, 1080.8*sx, 842.1*sy);

    const link = document.createElement('a');
    link.download = filePrefix+user.username+'.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
    toast('⬇️','Certificate downloaded!',toastMsg);
  };
  img.src = templateURI;
}

/* =========================================================
   21. SUPABASE: DATA FUNCTIONS
   One group per table. Each reads the Supabase user id from
   localStorage key passquest_user_id (set at registration).
   ========================================================= */
// ---- Save new user OR recognize existing one by email ----
async function saveOrGetUser(fullName, email, gradeLevel, section) {
  // Check if this email is already registered
  const { data: existingUsers, error: fetchError } = await sb
    .from("users")
    .select("*")
    .eq("email", email);

  if (fetchError) {
    console.error("Error checking existing user:", fetchError);
    return;
  }

  if (existingUsers.length > 0) {
    const existingUser = existingUsers[0];
    localStorage.setItem("passquest_user_id", existingUser.id);
    console.log("Welcome back:", existingUser);
    return existingUser;
  }

  // New user - insert and get their new id back
  const { data: newUser, error: insertError } = await sb
    .from("users")
    .insert([{ full_name: fullName, email: email, grade_level: gradeLevel, section: section }])
    .select()
    .single();

  if (insertError) {
    console.error("Error saving user:", insertError);
    return;
  }

  localStorage.setItem("passquest_user_id", newUser.id);
  console.log("New user saved:", newUser);
  return newUser;
}

// ---- Check if a user is already "remembered" on page load ----
async function getCurrentUser() {
  const userId = localStorage.getItem("passquest_user_id");
  if (!userId) {
    console.log("No signed-up user yet.");
    return null;
  }

  const { data, error } = await sb
    .from("users")
    .select("*")
    .eq("id", userId)
    .single();

  if (error) {
    console.error("Error fetching current user:", error);
    return null;
  }

  console.log("Current user:", data);
  return data;
}

