async function saveChecklistResponse(checklistItemId, completed) {
  const userId = localStorage.getItem("passquest_user_id");

  if (!userId) {
    console.log("No user signed up yet.");
    return;
  }

  const { data: existing, error: fetchError } = await sb
    .from("checklist_responses")
    .select("*")
    .eq("user_id", userId)
    .eq("checklist_item_id", checklistItemId);

  if (fetchError) {
    console.error("Error checking existing response:", fetchError);
    return;
  }

  if (existing.length > 0) {
    const { data, error } = await sb
      .from("checklist_responses")
      .update({ completed: completed, completed_at: new Date().toISOString() })
      .eq("id", existing[0].id);

    if (error) {
      console.error("Error updating checklist response:", error);
    } else {
      console.log("Checklist response updated:", data);
    }
  } else {
    const { data, error } = await sb
      .from("checklist_responses")
      .insert([
        {
          user_id: parseInt(userId),
          checklist_item_id: checklistItemId,
          completed: completed
        }
      ]);

    if (error) {
      console.error("Error saving checklist response:", error);
    } else {
      console.log("Checklist response saved:", data);
    }
  }
}


