  if (fetchError) { console.error("Error checking progress:", fetchError); return; }

  if (existing.length > 0) {
    const { data, error } = await sb.from("user_progress")
      .update({ completed, xp_earned: xpEarned, completed_at: new Date().toISOString() })
      .eq("id", existing[0].id);
    if (error) console.error("Error updating progress:", error);
    else console.log("Progress updated:", data);
  } else {
    const { data, error } = await sb.from("user_progress")
      .insert([{ user_id: parseInt(userId), lesson_id: lessonId, completed, xp_earned: xpEarned }]);
    if (error) console.error("Error saving progress:", error);
    else console.log("Progress saved:", data);
  }
  // leaderboard updates now happen only for opted-in students (syncLeaderboardEntry)
