async function saveCertificate() {
  const userId = localStorage.getItem("passquest_user_id");
  if (!userId) { console.log("No user signed up yet."); return; }

  const { data: existing, error: fetchError } = await sb
    .from("certificates").select("*").eq("user_id", userId);
  if (fetchError) { console.error("Error checking certificate:", fetchError); return; }

  if (existing.length > 0) {
    console.log("Certificate already issued:", existing[0]);
    return existing[0];
  }

  const certificateNumber = Date.now();

  const { data, error } = await sb.from("certificates")
    .insert([{ user_id: parseInt(userId), certificate_number: certificateNumber, verified: true }])
    .select().single();

  if (error) { console.error("Error saving certificate:", error); return; }
  console.log("Certificate issued:", data);
  return data;
}

